import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import path from 'node:path';import os from 'node:os';
import {stageBrowserExtension,changelogEntries} from '../scripts/build-browser-extension.mjs';import {pathToFileURL} from 'node:url';
async function fixture(t){const root=await fs.mkdtemp(path.join(os.tmpdir(),'extension-source-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));await fs.mkdir(path.join(root,'browser-extension'),{recursive:true});await fs.mkdir(path.join(root,'src/shared/surface'),{recursive:true});const manifest={manifest_version:3,action:{default_popup:'popup.html'},background:{service_worker:'background.js',type:'module'},permissions:['contextMenus','nativeMessaging']};await fs.writeFile(path.join(root,'browser-extension/manifest.json'),JSON.stringify(manifest));await fs.writeFile(path.join(root,'browser-extension/popup.html'),'<script type="module" src="popup.js"></script>');await fs.writeFile(path.join(root,'browser-extension/popup.js'),"import './vendor/material.js'; import './vendor/search.js';");await fs.writeFile(path.join(root,'browser-extension/background.js'),'const host="fixed";');for(const shared of ['preferences.js','accent.js'])await fs.writeFile(path.join(root,'browser-extension',shared),'export{};');await fs.writeFile(path.join(root,'src/shared/surface/material.js'),'// Vendor source: @material/web 2.5.0; esbuild 0.25.11.\nexport{};');const compile=async({entry,output})=>fs.writeFile(output,entry.endsWith('search-entry.js')?'new URL("./regex-worker.js",import.meta.url);':'self.onmessage=()=>{};');return{root,manifest,compile};}
test('extension stage contains local Material/shared search/worker and truthful unsigned receipt',async t=>{const{root,compile}=await fixture(t),receipt=await stageBrowserExtension({root,compile});assert.equal(receipt.signature,'not-produced');assert.equal(receipt.installation,'not-performed');assert.deepEqual(receipt.files.filter(row=>row.path.startsWith('vendor/')).map(row=>row.path),['vendor/material.js','vendor/search.js','vendor/regex-worker.js']);const manifest=JSON.parse(await fs.readFile(path.join(root,'out/browser-extension/manifest.json'),'utf8'));assert.match(manifest.content_security_policy.extension_pages,/worker-src 'self'/);});
test('extension staging rejects elevated permissions and remote popup scripts',async t=>{const{root,manifest,compile}=await fixture(t);await fs.writeFile(path.join(root,'browser-extension/manifest.json'),JSON.stringify({...manifest,permissions:[...manifest.permissions,'downloads']}));await assert.rejects(stageBrowserExtension({root,compile}),/permissions/);await fs.writeFile(path.join(root,'browser-extension/manifest.json'),JSON.stringify(manifest));await fs.writeFile(path.join(root,'browser-extension/popup.html'),'<script src="https://example.com/code.js"></script>');await assert.rejects(stageBrowserExtension({root,compile}),/external/);});
test('missing shared regex worker route cannot produce a successful bundle receipt',async t=>{const{root}=await fixture(t);await assert.rejects(stageBrowserExtension({root,compile:async({output})=>fs.writeFile(output,'export{};')}),/worker route/);});

test('production options workspace is hashed and staged under local-only CSP',async t=>{const destination=await fs.mkdtemp(path.join(os.tmpdir(),'extension-workspace-output-'));t.after(()=>fs.rm(destination,{recursive:true,force:true}));const receipt=await stageBrowserExtension({root:process.cwd(),destination:path.join(destination,'stage'),compile:async({entry,output})=>fs.writeFile(output,entry.endsWith('search-entry.js')?'new URL("./regex-worker.js",import.meta.url);':'self.onmessage=()=>{};')});for(const file of ['options.html','options.js','options.css','preferences.js'])assert.ok(receipt.files.some(row=>row.path===file&&row.sha256.length===64));const manifest=JSON.parse(await fs.readFile(path.join(destination,'stage/manifest.json'),'utf8'));assert.equal(manifest.options_ui.page,'options.html');assert.match(manifest.content_security_policy.extension_pages,/connect-src 'none'/);assert.deepEqual(manifest.permissions,['contextMenus','nativeMessaging']);for(const file of ['vendor/changelog.js','vendor/provenance.js'])assert.ok(receipt.files.some(row=>row.path===file&&row.sha256.length===64),file);const changelog=(await import(pathToFileURL(path.join(destination,'stage/vendor/changelog.js')).href)).default;assert.equal(changelog.schemaVersion,1);assert.ok(changelog.entries.length>0&&changelog.entries[0].title&&Array.isArray(changelog.entries[0].items));const provenance=(await import(pathToFileURL(path.join(destination,'stage/vendor/provenance.js')).href)).default;assert.equal(provenance.version,manifest.version);assert.ok(provenance.sourceCommit===null||/^[0-9a-f]{40}$/.test(provenance.sourceCommit));assert.ok([true,false,null].includes(provenance.sourceModified));assert.ok(!Number.isNaN(Date.parse(provenance.stagedAtUtc)));});
test('changelog parsing keeps release entries, items and the Cantonese summary',()=>{const entries=changelogEntries('# First, 2026-10-14\r\n\r\n- One\n- Two\n\n第一個\n## Older - 2026-10-01\n- Three');assert.deepEqual(entries,[{title:'First',date:'2026-10-14',items:['One','Two'],yue:'第一個'},{title:'Older',date:'2026-10-01',items:['Three'],yue:''}]);});
